PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE products (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  brand TEXT,
  category TEXT,
  price REAL NOT NULL,
  stock INTEGER DEFAULT 0,
  image_url TEXT,
  description TEXT,
  is_hidden INTEGER DEFAULT 0,
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE orders (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  customer_name TEXT NOT NULL,
  customer_phone TEXT NOT NULL,
  customer_address TEXT,
  total REAL NOT NULL,
  status TEXT DEFAULT 'pending',
  created_at TEXT DEFAULT CURRENT_TIMESTAMP
, location_lat REAL, location_lng REAL);
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT,
  updated_at TEXT DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE offers (id INTEGER PRIMARY KEY AUTOINCREMENT, title TEXT NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL, offer_price REAL NOT NULL, created_at TEXT DEFAULT CURRENT_TIMESTAMP, expires_at TEXT, manual_price REAL DEFAULT NULL);
CREATE TABLE offer_items (id INTEGER PRIMARY KEY AUTOINCREMENT, offer_id INTEGER NOT NULL, product_id INTEGER NOT NULL, quantity INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS "order_items" (id INTEGER PRIMARY KEY AUTOINCREMENT, order_id INTEGER NOT NULL, product_id INTEGER, offer_id INTEGER, quantity INTEGER NOT NULL, price REAL NOT NULL, item_name TEXT);
DELETE FROM sqlite_sequence;
